                if (ds.colombiaDetected) detected++;
                if (ds.mexicoDetected) detected++;
                if (ds.spainDetected) detected++;
                ds.issuesDetected = detected;
                roundScore = detected * 100;
                details = this._tr('det_issues', '{n} of 3 issues detected').split('{n}').join(detected);
            } else if (period === 2) {
                roundName = this._tr('rn_2', 'Consolidation');
                var pts = 0;
                var maxPts = 5;
                var icTarget = 2400000;
                var upTarget = 120000;
                var fxCloseTarget = 1.08;
                var fxAvgTarget = 1.10;
                var nciTarget = 30;

                var r2 = {
                    ic: Math.abs(d.icRevenueElim - icTarget) / icTarget < 0.02,
                    up: Math.abs(d.unrealizedProfit - upTarget) / upTarget < 0.05,
                    close: Math.abs(d.fxClosingRate - fxCloseTarget) < 0.005,
                    avg: Math.abs(d.fxAverageRate - fxAvgTarget) < 0.005,
                    nci: Math.abs(d.nciPercent - nciTarget) < 1,
                    icVal: d.icRevenueElim, upVal: d.unrealizedProfit,
                    closeVal: d.fxClosingRate, avgVal: d.fxAverageRate, nciVal: d.nciPercent
                };
                ['ic', 'up', 'close', 'avg', 'nci'].forEach(function(k) { if (r2[k]) pts++; });
                ds.trace = ds.trace || {};
                ds.trace.r2 = r2;

                roundScore = Math.round((pts / maxPts) * 250);
                ds.consolidationScore = roundScore;
                details = this._tr('det_items', '{n} of {m} items correct').split('{n}').join(pts).split('{m}').join(maxPts);
            } else if (period === 3) {
                roundName = this._tr('rn_3', 'IFRS Adjustments');
                var pts3 = 0;
                var maxPts3 = 200;
                var r3 = { ifrs15: 0, ifrs16: 0, lease: 0, ifrs15Val: d.ifrs15Adjustment, leaseVal: d.ifrs16Amount };

                var ifrs15Target = 600000;
                if (Math.abs(d.ifrs15Adjustment - ifrs15Target) / ifrs15Target < 0.05) {
                    pts3 += 100; r3.ifrs15 = 100;
                } else if (Math.abs(d.ifrs15Adjustment - ifrs15Target) / ifrs15Target < 0.15) {
                    pts3 += 50; r3.ifrs15 = 50;
                }

                if (d.ifrs16Decision === 'capitalize') {
                    pts3 += 50; r3.ifrs16 = 50;
                    var leaseTarget = 869400;
                    if (Math.abs(d.ifrs16Amount - leaseTarget) / leaseTarget < 0.05) {
                        pts3 += 50; r3.lease = 50;
                    } else if (Math.abs(d.ifrs16Amount - leaseTarget) / leaseTarget < 0.15) {
                        pts3 += 25; r3.lease = 25;
                    }
                }

                // The goodwill conclusion is booked now; the auditor settles it at sign-off (Round 4).
                ds.ias36Decision = d.ias36Decision;
                ds.ifrs16Decision = d.ifrs16Decision;
                ds.trace = ds.trace || {};
                ds.trace.r3 = r3;

                roundScore = pts3;
                ds.ifrsScore = roundScore;
                details = this._tr('det_points3', '{n} of {m} points; the IAS 36 conclusion goes to the audit review').split('{n}').join(roundScore).split('{m}').join(maxPts3);
            } else if (period === 4) {
                roundName = this._tr('rn_4', 'Audit Interaction');
                var pts4 = 0;
                if (d.audit1 === 'accept') pts4 += 100; else pts4 += 30;
                if (d.audit2 === 'defend') pts4 += 100; else pts4 += 30;
                if (d.audit3 === 'defend') pts4 += 100; else pts4 += 30;
                // The Round-3 goodwill conclusion survives the audit review only if it follows the test.
                if (ds.ias36Decision === 'not_impaired') pts4 += 100;
                // What management left in the accounts, the auditor finds: each undetected Round-1 issue
                // and a lease left off the balance sheet becomes an audit finding at sign-off.
                var findings = (3 - (ds.issuesDetected || 0)) + (ds.ifrs16Decision === 'capitalize' ? 0 : 1);
                ds.auditFindings = findings;
                pts4 = Math.max(0, pts4 - 50 * findings);
                roundScore = pts4;
                ds.auditScore = roundScore;
                ds.trace = ds.trace || {};
                ds.trace.r4 = { a1: d.audit1, a2: d.audit2, a3: d.audit3, findings: findings };
                details = this._tr('det_points4', '{n} of {m} points; audit findings: {f}').split('{n}').join(roundScore).split('{m}').join(400).split('{f}').join(findings);
            }

            ds.score += roundScore;
            ds.roundScores.push(roundScore);
            ds.scoreHistory.push(ds.score);
            ds.roundNames.push(roundName);

            // Platform score: the cumulative points that getPerformanceSummary totals, out of its maxPossible 1150, scaled to 0-100.
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: Math.max(0, Math.min(100, Math.round(100 * ds.score / 1150))) });

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return {
                period: period,
                roundName: roundName,
                roundScore: roundScore,
                cumulativeScore: ds.score,
                findings: ds.auditFindings,
                details: details,
                overallScore: ds.performance.overallScore,
                score: ds.performance.overallScore
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.score',
                (v) => Math.round(v).toLocaleString() + ' pts');
            uiManager.bind('issuesDisplay', 'domainState.issuesDetected',
                (v) => v + ' / 3');
            uiManager.bind('consolidationDisplay', 'domainState.consolidationScore',
                (v) => v > 0 ? v + ' / 250' : '\u2014');
            uiManager.bind('auditDisplay', 'domainState.auditScore',
                (v) => v > 0 ? v + ' / 400' : '\u2014');

            var colInput = document.getElementById('colombiaHoursInput');
            var mxInput = document.getElementById('mexicoHoursInput');
            var spInput = document.getElementById('spainHoursInput');
            var totalDisp = document.getElementById('totalHoursDisplay');

            function updateTotal() {
                var t = (parseInt(colInput.value) || 0) + (parseInt(mxInput.value) || 0) + (parseInt(spInput.value) || 0);
                if (totalDisp) totalDisp.textContent = t;
            }
            if (colInput) colInput.addEventListener('input', updateTotal);
            if (mxInput) mxInput.addEventListener('input', updateTotal);
            if (spInput) spInput.addEventListener('input', updateTotal);
            updateTotal();

            var self = this;
            var repaint = function() {
                try { if (window.mySimulation && window.mySimulation.state) self._updateBriefing(window.mySimulation.state); } catch (e) {}
            };
            if (!this._langBound) {
                this._langBound = true;
                document.addEventListener('express:langchanged', function() { setTimeout(repaint, 0); });
                try {
                    if (window.mySimulation && window.mySimulation.eventBus) window.mySimulation.eventBus.on('language:changed', function() { setTimeout(repaint, 0); });
                } catch (e) {}
            }
        }

        getChartConfig() {
            return {
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: this._tr('chart_round_score', 'Round Score'),
                            data: [],
                            backgroundColor: [
                                'rgba(0,150,136,0.7)',
                                'rgba(3,169,244,0.7)',
                                'rgba(156,39,176,0.7)',
                                'rgba(255,152,0,0.7)'
                            ],
                            borderColor: [
                                '#009688',
                                '#03a9f4',
                                '#9c27b0',
                                '#ff9800'
                            ],
                            borderWidth: 2,
                            borderRadius: 6
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: this._tr('chart_score_title', 'Score by Round'), color: '#e0e0e0' },
                            legend: { labels: { color: '#b0bec5' } }
                        },
                        scales: {
                            y: {
                                beginAtZero: true,
