        }

        getChartData(state) {
            var self = this;
            return {
                scoreChart: {
                    labels: state.domainState.roundNames.map(function(n, i) { return self._tr('rn_' + (i + 1), n); }),
                    datasets: [{ data: state.domainState.roundScores, label: self._tr('chart_round_score', 'Round Score') }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results ? r.results.roundScore || 0 : 0; });
            var totalScore = scores.reduce(function(s, v) { return s + v; }, 0);

            // Bands on the platform score (0-100), derived from the sweep: expert play 100, random median about 44.
            var pct = Math.max(0, Math.min(100, Math.round(100 * totalScore / 1150)));
            var tier = this._band(pct);
            var ds = {};
            try { ds = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {}; } catch (e) {}
            var deb = this._debrief(ds, history);

            return {
                totalScore: totalScore,
                maxPossible: 1150,
                overallScore: pct,
                score: pct,
                composite: pct,
                performance: tier,
                performanceKey: tier,
                performanceLabel: this._tr('perf_' + tier, tier),
                insights: deb.insights,
                turningPoint: deb.turningPoint,
                questions: deb.questions,
                judgementScore: deb.judgement,
                mechanicsScore: deb.mechanics,
                issuesDetected: ds.issuesDetected || 0,
                consolidationScore: ds.consolidationScore || 0,
                auditScore: ds.auditScore || 0,
                auditFindings: ds.auditFindings || 0
            };
        }

        // Run-specific debrief: every point lost is traced to the decision that lost it (EQIL 15.2, S4, B12).
        _debrief(ds, history) {
            var self = this, T = function(k, f) { return self._tr(k, f); };
            var tr = ds.trace || {}, r2 = tr.r2 || {}, r3 = tr.r3 || {}, r4 = tr.r4 || {};
            var near = function(v, x, tol) { return typeof v === 'number' && Math.abs(v - x) <= Math.abs(x) * (tol || 0.02); };
            var losses = [], good = [];
            var add = function(pts, text) { if (pts > 0 && text) losses.push({ pts: pts, text: text }); };
            var played = function(p) { return history.some(function(h) { return h && h.period === p; }); };

            if (played(1)) {
                var missed = [];
                if (!ds.colombiaDetected) missed.push(T('sub_col', 'Colombia'));
                if (!ds.mexicoDetected) missed.push(T('sub_mex', 'Mexico'));
                if (!ds.spainDetected) missed.push(T('sub_spa', 'Spain'));
                if (missed.length) add(150 * missed.length, T('ins_r1_missed', '{subs} went without enough review: the issue stayed in the accounts and the auditor found it at sign-off. Coverage before conviction: a minimum on every entity first, then concentrate.').split('{subs}').join(missed.join(', ')));
                else good.push(T('good_r1', 'Your review hours covered all three subsidiaries, so every issue was yours to fix, not the auditor’s to find.'));
            }
            if (played(2)) {
                var single = (typeof r2.closeVal === 'number' && r2.closeVal === r2.avgVal);
                var noElim = (r2.icVal === 0 && r2.upVal === 0);
                if (single || noElim) {
                    var lostS = (r2.ic ? 0 : 50) + (r2.up ? 0 : 50) + (r2.close ? 0 : 50) + (r2.avg ? 0 : 50);
                    add(lostS, T('ins_r2_shortcut', 'The year-end shortcut: one rate for every line and no quarter-end eliminations. It is quick, but the group reports a sale to itself as revenue and a translation difference that never reaches OCI.'));
                } else {
                    if (!r2.ic) add(50, near(r2.icVal, 480000) ? T('ins_r2_ic_unsold', 'You eliminated intragroup revenue only on the goods still in Spain’s inventory. The group sold nothing to itself: the whole $2.4M sale comes out of revenue.') : T('ins_r2_ic', 'The intercompany revenue elimination was off: the whole intragroup sale comes out of consolidated revenue.'));
                    if (!r2.up) add(50, near(r2.upVal, 600000) ? T('ins_r2_up_all', 'You removed the margin on the whole sale. Only the margin on goods still inside the group is unrealised; the goods Spain resold earned a real profit.') : T('ins_r2_up', 'The unrealised profit was off: only the margin on the goods still in inventory comes out (unsold share times margin).'));
                    if (!r2.close || !r2.avg) {
                        var swapped = near(r2.closeVal, 1.10, 0.004) && near(r2.avgVal, 1.08, 0.004);
                        var opening = near(r2.closeVal, 1.12, 0.004) || near(r2.avgVal, 1.12, 0.004);
                        add((r2.close ? 0 : 50) + (r2.avg ? 0 : 50), swapped ? T('ins_r2_fx_swap', 'You swapped the two rates. IAS 21: the closing rate goes to the balance sheet, the average rate to the income statement, and the difference to OCI.') : opening ? T('ins_r2_fx_open', 'You used the opening rate. Under IAS 21 the balance sheet takes the closing rate and the income statement the average for the period.') : T('ins_r2_fx', 'A translation rate was off: closing rate for the balance sheet, average rate for the income statement.'));
                    }
                }
                if (!r2.nci) add(50, near(r2.nciVal, 70, 0.01) ? T('ins_r2_nci_parent', 'You entered the parent’s 70%, not the non-controlling interest: NCI is the 30% the group does not own.') : T('ins_r2_nci', 'The NCI percentage was off: it is the share of Colombia the parent does not own.'));
                if (r2.ic && r2.up && r2.close && r2.avg && r2.nci) good.push(T('good_r2', 'The consolidation worksheet was right on all five lines: full elimination of the sale, margin only on unsold goods, closing and average rates in their places.'));
            }
            if (played(3)) {
                if (r3.ifrs15 < 100) add(100 - (r3.ifrs15 || 0), near(r3.ifrs15Val, 750000) ? T('ins_r3_15_ssp', 'You reversed the service at its standalone price. IFRS 15 allocates the contract price by relative standalone selling prices, so the bundle discount is shared.') : near(r3.ifrs15Val, 2000000) ? T('ins_r3_15_all', 'You reversed the whole contract. The equipment was delivered; only the service allocation is unearned.') : T('ins_r3_15', 'The IFRS 15 reversal was off: allocate the contract price by relative standalone selling price and reverse only the undelivered part.'));
                if (ds.ifrs16Decision && ds.ifrs16Decision !== 'capitalize') add(150, T('ins_r3_16_expense', 'You kept the Colombia lease as a short-term expense. A 60-month lease is not short-term, so the liability stayed off the balance sheet and the auditor raised it at sign-off.'));
                else if (r3.lease < 50) add(50 - (r3.lease || 0), near(r3.leaseVal, 1095540) ? T('ins_r3_16_undisc', 'You booked the undiscounted payments. IFRS 16 measures the liability at the present value of the payments, at the incremental borrowing rate.') : T('ins_r3_16_amt', 'The lease liability was off: discount the 60 payments at the incremental borrowing rate.'));
            }
            var impairedR3 = ds.ias36Decision === 'impaired';
            var conceded3 = r4.a3 === 'accept';
            if (impairedR3 || conceded3) {
                add((impairedR3 ? 100 : 0) + (conceded3 ? 70 : 0), T('ins_prudence', 'The prudence reflex: Spain’s goodwill was written down because EBIT missed budget by 22%, yet value in use on the revised forecast ($33.0M) still covers the carrying amount ($31.5M). An indicator obliges a test; it is not the conclusion, and a goodwill write-down can never be reversed.'));
            } else if (played(4)) {
                good.push(T('good_ias36', 'You tested Spain’s goodwill instead of reacting to the 22% miss, and held that conclusion under audit challenge.'));
            }
            if (played(4)) {
                if (r4.a1 === 'accept' && r4.a2 === 'accept' && r4.a3 === 'accept') {
                    add(70, T('ins_r4_all', 'You conceded all three queries to close without open findings. Management owns the statements: a reasonable, immaterial estimate given up to buy a quiet sign-off is a misstatement too.'));
                } else {
                    if (r4.a2 === 'accept') add(70, T('ins_r4_rate', 'You accepted the 10.2% rate. On this lease the difference is about $14,000 (1.6%): an immaterial, entity-specific estimate you could defend.'));
                }
                if (r4.a1 === 'defend') add(70, T('ins_r4_warranty', 'You defended the warranty provision against updated claims data. New evidence moves the best estimate (IAS 37): that adjustment was the one to accept.'));
            }

            losses.sort(function(a, b) { return b.pts - a.pts; });
            var insights = losses.slice(0, 4).map(function(l) { return l.text; });
            for (var i = 0; insights.length < 3 && i < good.length; i++) insights.push(good[i]);
            var turningPoint = losses.length
                ? T('tp_lost', 'The decision that cost you most ({n} points): {txt}').split('{n}').join(losses[0].pts).split('{txt}').join(losses[0].text)
                : T('tp_none', 'No decision cost you points: the close followed the evidence at every step.');

            var judgement = (history.filter(function(h) { return h.period === 1 || h.period === 4; })
                .reduce(function(s, h) { return s + ((h.results && h.results.roundScore) || 0); }, 0)) + (r3.ifrs16 || 0);
            var mechanics = (ds.consolidationScore || 0) + (r3.ifrs15 || 0) + (r3.lease || 0);
            return {
                insights: insights,
                turningPoint: turningPoint,
                questions: [T('q_1', 'What evidence would have turned Spain’s 22% miss from an indicator into an impairment?'),
                            T('q_2', 'Why is the revenue you eliminate on an intragroup sale not the profit you eliminate?'),
                            T('q_3', 'When does accepting an auditor’s proposal become a misstatement of its own?')],
                judgement: judgement,
                mechanics: mechanics
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var self = this, T = function(k, f) { return self._tr(k, f); };
            var esc = function(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
            var li = function(arr) { return (arr || []).map(function(x) { return '<li>' + esc(x) + '</li>'; }).join(''); };
            var kpi = function(label, val) { return '<div class="closebooks-cm-kpi"><span class="closebooks-cm-kpi-label">' + esc(label) + '</span><span class="closebooks-cm-kpi-value">' + esc(val) + '</span></div>'; };
            return '<div class="closebooks-cm" role="region" aria-label="' + esc(T('cm_title', 'Close debrief')) + '">' +
                '<h3 class="closebooks-cm-title">' + esc(T('cm_title', 'Close debrief')) + '</h3>' +
                '<p class="closebooks-cm-score"><strong>' + esc(summary.overallScore) + '/100</strong> · ' + esc(summary.performanceLabel || '') + '</p>' +
                '<div class="closebooks-cm-kpis">' +
                    kpi(T('cm_judgement', 'Judgement'), (summary.judgementScore || 0) + ' / 750') +
                    kpi(T('cm_mechanics', 'Calculation'), (summary.mechanicsScore || 0) + ' / 400') +
                    kpi(T('issues_label', 'Issues Detected'), (summary.issuesDetected || 0) + ' / 3') +
                    kpi(T('cm_findings', 'Audit findings'), String(summary.auditFindings || 0)) +
                '</div>' +
                '<h4 class="closebooks-cm-h">' + esc(T('cm_turning', 'Turning point')) + '</h4><p>' + esc(summary.turningPoint || '') + '</p>' +
                '<h4 class="closebooks-cm-h">' + esc(T('cm_insights', 'What this run shows')) + '</h4><ul>' + li(summary.insights) + '</ul>' +
                '<h4 class="closebooks-cm-h">' + esc(T('cm_questions', 'For class discussion')) + '</h4><ul>' + li(summary.questions) + '</ul>' +
                '</div>';
        }

        // One function for the verdict band: excellent >= 90, good >= 75, developing >= 50 (platform score 0-100).
        _band(pct) {
            if (pct >= 90) return 'excellent';
            if (pct >= 75) return 'good';
            if (pct >= 50) return 'developing';
            return 'insufficient';
        }

        getHint(state, results) {
            if (!results) return null;
            var period = results.period;
            if (period === 1 && state.domainState.issuesDetected < 3) {
                return window.mySimulation.t('hint_missed_issues');
            }
            if (period === 2 && state.domainState.consolidationScore < 150) {
                return window.mySimulation.t('hint_consolidation_weak');
            }
            if (period === 3 && state.domainState.ifrsScore < 150) {
                return window.mySimulation.t('hint_ifrs_weak');
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.roundName', label: 'Round', i18nKey: 'col_round',
                  formatter: (v, entry) => (entry && entry.period) ? this._tr('rn_' + entry.period, v) : v },
                { key: 'results.roundScore', label: 'Score', i18nKey: 'col_score' },
                { key: 'results.cumulativeScore', label: 'Cumulative', i18nKey: 'col_cumulative' },
                { key: 'results.details', label: 'Details', i18nKey: 'col_details',
                  formatter: (v, entry) => this._details(entry, v) }
            ];
        }

        getPresets() { return null; }

        // Translation lookup with the authored English as fallback, safe before the framework is ready.
        _tr(key, fallback) {
            try {
                var v = window.mySimulation.t(key);
                if (v && v !== key) return v;
            } catch (e) {}
            return fallback;
        }

        // History details rebuilt in the current language from the stored round numbers.
        _details(entry, fallback) {
            var r = entry && entry.results;
            if (!r || !r.period) return fallback;
            if (r.period === 1) return this._tr('det_issues', '{n} of 3 issues detected').split('{n}').join(Math.round((r.roundScore || 0) / 100));
            if (r.period === 2) return this._tr('det_items', '{n} of {m} items correct').split('{n}').join(Math.round((r.roundScore || 0) / 50)).split('{m}').join(5);
            return this._tr('det_points', '{n} of {m} points').split('{n}').join(r.roundScore || 0).split('{m}').join(300);
        }

        getTranslations() {
            return {
                en: {
                    title:                `CloseTheBooks: Financial Reporting, Consolidation & IFRS`,
                    subtitle:             `Q3 Financial Close — Condor Holdings`,
                    round_label:          `Round`,
                    period_of:            `of`,
                    score_label:          `Total Score`,
                    issues_label:         `Issues Detected`,
                    consolidation_label:  `Consolidation Accuracy`,
                    audit_label:          `Audit Score`,
                    round1_name:          `Round 1: Subsidiary Close Review`,
                    round1_briefing:      `Allocate 12 review hours across three subsidiaries. Each subsidiary has submitted Q3 trial balances. Your task: identify reporting issues before consolidation begins. An issue surfaces only if its subsidiary gets enough review time; whatever you miss stays in the accounts for the auditor to find at sign-off.`,
                    round2_name:          `Round 2: Consolidation Mechanics`,
                    round2_briefing:      `Perform the group consolidation from the case file below: eliminate intercompany transactions between Mexico and Spain, translate the Spain subsidiary financials from EUR to USD using IAS 21, and calculate non-controlling interest for the 70%-owned Colombia subsidiary.`,
                    round3_name:          `Round 3: IFRS Adjustment Package`,
                    round3_briefing:      `Three IFRS issues require resolution: (1) IFRS 15 — Mexico revenue recognition for a bundled contract, (2) IFRS 16 — Colombia lease misclassified as short-term, (3) IAS 36 — Spain goodwill impairment indicator. Quantify each adjustment from the case file below.`,
                    round4_name:          `Round 4: Audit Interaction & Sign-off`,
                    round4_briefing:      `The external auditors have raised three queries on your consolidated accounts. For each, decide whether to accept their proposed adjustment or defend your original position with IFRS-grounded reasoning.`,
                    r1_heading:           `Review Hour Allocation`,
                    r1_hint:              `You have 12 review hours. Allocate them wisely across subsidiaries to maximize issue detection.`,
                    r1_colombia_label:    `Colombia (70% owned, COP) — Hours`,
                    r1_mexico_label:      `Mexico (100% owned, MXN) — Hours`,
                    r1_spain_label:       `Spain (100% owned, EUR) — Hours`,
                    r1_total_prefix:      `Total hours allocated:`,
                    r2_heading:           `Consolidation Worksheet`,
                    r2_hint:              `Enter the correct elimination and translation amounts for the group consolidation.`,
                    r2_ic_revenue_label:  `Intercompany Revenue Elimination ($)`,
