        _updateBriefing(state) {
            var cp = (state.currentPeriod || 1);
            var over = cp > this.ROUNDS.length;
            var idx = Math.min(cp - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('roundTitle');
            if (titleEl && !over) {
                var translatedName = window.mySimulation ? window.mySimulation.t(round.nameKey) : round.nameDefault;
                if (!translatedName || translatedName === round.nameKey) translatedName = round.nameDefault;
                titleEl.textContent = translatedName;
            }

            var briefEl = document.getElementById('briefingText');
            if (briefEl && !over) {
                var translatedBriefing = window.mySimulation ? window.mySimulation.t(round.briefingKey) : round.briefingDefault;
                if (!translatedBriefing || translatedBriefing === round.briefingKey) translatedBriefing = round.briefingDefault;
                briefEl.textContent = translatedBriefing;
            }

            var factsEl = document.getElementById('caseFacts');
            if (factsEl) {
                var facts = over ? '' : this._tr('facts_r' + cp, '');
                if (facts) {
                    var escH = function(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
                    factsEl.innerHTML = '<h4>' + escH(this._tr('facts_title', 'Case file')) + '</h4><ul>' +
                        facts.split('|').map(function(f) { return '<li>' + escH(f) + '</li>'; }).join('') + '</ul>';
                    factsEl.style.display = 'block';
                } else {
                    factsEl.innerHTML = '';
                    factsEl.style.display = 'none';
                }
            }
            var chartEl = document.getElementById('scoreChart');
            if (chartEl && chartEl.setAttribute) chartEl.setAttribute('aria-label', this._tr('chart_alt', 'Bar chart of the score by round; the same figures are in the history table.'));

            for (var i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) {
                    panel.style.display = (!over && i === idx) ? 'block' : 'none';
                }
            }

            if (over) {
                var b = document.getElementById('nextPeriodBtn');
                if (b) b.disabled = true;
                var u = document.getElementById('undoBtn');
                if (u) u.style.display = 'none';
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new CloseTheBooksAdapter(), {
            simulationType: 'closethebooks_212',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

})();
